ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'apps/devcat_flutter/assets/content'
GLOSSARY={
'basics':'Исходник — записанный текст программы. Выполнение — действия по этому тексту. Ввод — данные, которые программа получает. Вывод — то, что она сообщает. Эти четыре вещи нужно различать даже в первой задаче.',
'values':'Тип задаёт правила операций с данными. Целое число 12 подходит для счёта, строка "12" хранит два символа. Значение выражения вычисляется до его использования во внешней операции. Не определяй тип только по внешнему виду напечатанного результата.',
'variables':'Имя позволяет обратиться к сохранённым данным. Присваивание заменяет значение, а сравнение задаёт вопрос. Сначала вычисляется правая часть, затем изменяется левая. В таблице состояния каждому моменту выполнения соответствует своё значение имени.',
'operators':'Оператор — знак действия. Выражение объединяет значения и операции. Приоритет определяет порядок без скобок; скобки задают его явно. Остаток от деления отличается от частного. Например, 135 секунд содержат 2 полные минуты и остаток 15 секунд.',
'input':'Чтение получает данные, преобразование придаёт им нужный тип, проверка отвергает недопустимое, вычисление получает ответ. Не смешивай эти шаги. Сначала запусти корректный вход, затем отдельно проверь пустую строку и текст вместо числа.',
'logic':'Логическое выражение отвечает «да» или «нет». Сравнение не меняет сравниваемые числа. И требует истинности обеих частей, ИЛИ — хотя бы одной. Отрицание меняет ответ на противоположный. Правило «не младше 18» включает ровно 18.',
'conditions':'Ветка — один возможный путь выполнения. Условие выбирает путь. В одном if/else выполняется одна из двух частей. Не путай вложенную проверку и следующую независимую проверку. Для понимания сначала проследи один конкретный вход по стрелкам.',
'loops':'Тело — повторяемые команды. Итерация — одно повторение. Условие продолжения проверяет, нужен ли следующий шаг. Накопитель хранит результат уже выполненных шагов. Если он обнуляется в теле, прежний итог теряется.',
'nested':'Внешний цикл выбирает одну группу, внутренний полностью обрабатывает её элементы. Для двух строк и трёх столбцов получаются шесть пар: (0,0),(0,1),(0,2),(1,0),(1,1),(1,2). Выпиши пары до запуска, чтобы не перепутать порядок.',
'strings':'Строка — текстовое значение. Индекс — номер позиции по правилам языка; обычно первая позиция нулевая. Длина и последняя допустимая позиция различаются на один. Байт, символ Unicode и видимый знак не всегда совпадают. Сначала изучаем простой латинский пример, потом кириллицу.',
'arrays':'Коллекция хранит несколько значений. Элемент — одно значение, индекс — способ выбрать позицию. Для трёх элементов допустимы индексы 0,1,2. Число 3 является длиной, но не допустимым индексом. Изменение элемента отличается от изменения размера коллекции.',
'functions':'Функция — именованное действие с входными параметрами и возможным результатом. Определение описывает действие, вызов запускает его. Аргумент — конкретное переданное значение, параметр — имя внутри функции. return передаёт результат вызывающему коду; печать только показывает текст.',
'maps':'Ключ позволяет найти связанное значение. В словаре частот ключом может быть слово, значением — число встреч. Перед увеличением счётчика нужно определить значение для ещё не встречавшегося ключа. Порядок обхода и уникальность ключей — разные свойства.',
'files':'Путь указывает, какой файл открыть. Чтение получает его содержимое, запись меняет данные на диске. Относительный путь отсчитывается от рабочей папки запуска. Закрытие освобождает ресурс. Проверяй отсутствие файла и отказ доступа отдельно от ошибки формата данных.',
'errors':'Ошибка входа, ошибка программы и отсутствие среды запуска — разные причины. Обработчик должен объяснять конкретную причину, а не прятать всё словом «успех». Начни с одного корректного примера и одного неправильного, затем сравни, на каком шаге они расходятся.',
'debugging':'Отладка — поиск причины отличия фактического результата от ожидаемого. Сначала нужен повторяемый вход. Затем ожидаемые промежуточные значения сравниваются с фактическими. Одна проверяемая гипотеза и одна правка полезнее десяти случайных замен.',
'search':'Линейный поиск проверяет элементы по одному. Двоичный поиск отбрасывает часть возможных ответов и требует упорядоченности или монотонного свойства. Сначала выпиши оставшийся диапазон вручную. Условие окончания должно сужать его, а не повторять тот же шаг.',
'sort':'Сортировка меняет порядок по правилу сравнения. Поиск минимума не обязательно требует сортировать всё. Одинаковые ключи могут иметь разный порядок: стабильность обещает сохранить относительный порядок равных элементов, если алгоритм действительно стабилен.'}

GLOSSARY['expressions']=GLOSSARY['operators']
GLOSSARY['booleans']=GLOSSARY['logic']
GLOSSARY['branches']=GLOSSARY['conditions']
GLOSSARY['collections']=GLOSSARY['maps']
GLOSSARY['scope']='Область видимости — часть исходника, где можно обратиться к имени. Время жизни — период, когда сами данные существуют. Это разные вещи. Локальная переменная функции обычно недоступна снаружи по её имени; сохранённая где-то ссылка не всегда продлевает жизнь данных. Сначала нарисуй границы блоков и посмотри, где имя объявлено.'
GLOSSARY['iteration']='Обход берёт элементы по очереди. Преобразование делает из каждого новое значение. Фильтрация сохраняет только подходящие элементы. Например, из [1,2,3,4] отбор чётных даёт [2,4], а удвоение затем даёт [4,8]. Перестановка операций может изменить смысл: сначала запиши промежуточные наборы.'
GLOSSARY['records']='Запись объединяет связанные свойства одного предмета. У книги могут быть название, цена и остаток. Объект — конкретный экземпляр такой модели. Две книги с одинаковым названием могут быть разными экземплярами; равенство значений и идентичность нужно различать. Сначала составь одну запись и прочитай каждое её поле.'
GLOSSARY['json']='JSON — текстовый формат обмена данными. Объект записывается в фигурных скобках, массив — в квадратных, имена свойств и текст — в двойных кавычках. Разбор текста создаёт значения программы, а сериализация снова создаёт текст. Корректная запись JSON не означает, что в ней есть все нужные приложению поля.'
GLOSSARY['modules']='Модуль отделяет часть программы и позволяет использовать её по имени. Импорт сообщает, где брать определённые возможности; он не заменяет сам вызов функции. Точка входа запускается первой, а вспомогательный файл предоставляет действия. Начни с функции сложения в одном файле, затем перенеси только её и проверь импорт.'
GLOSSARY['testing']='Тест — проверяемый пример: известный вход, ожидаемый результат и сравнение с фактическим. Пример 4 → 5 проверяет прибавление единицы на одном числе. Пример 0 → 1 проверяет другое число. Чтобы проверить границу, нужно взять значение на ней и по обе стороны. Совпадение одного результата не доказывает правильность всех случаев.'
GLOSSARY['complexity']='Сложность описывает, как меняется объём работы при росте входа. Один проход по 10 элементам делает около 10 однотипных шагов, по 100 — около 100. Это линейный рост O(n). Проверка каждой пары даёт примерно 100 шагов для 10 элементов и 10000 для 100: квадратичный рост O(n²). Это оценка роста, а не точное число миллисекунд.'
GLOSSARY['basics']+=' Контракт здесь — простое описание задачи: что получает программа, какие значения допустимы и какой ответ требуется. Это не отдельный файл и не юридический документ.'
GLOSSARY['loops']+=' Инвариант — утверждение, которое остаётся верным после каждого шага. В суммировании это простое правило: total равен сумме уже обработанных чисел. Сначала проследи 1, затем 1+2, затем 1+2+3, и только потом используй общее слово.'

def png(title,boxes):
 key=hashlib.sha256((title+'\n'+'\n'.join(boxes)).encode()).hexdigest()[:18]
 name='steps-'+key+'.png';path=OUT/name
 if path.exists():return name
 if Image is None:raise RuntimeError('Для создания новых схем установи Pillow; опубликованные схемы уже включены в git.')
 FONT=ImageFont.truetype(str(ROOT/'apps/devcat_flutter/assets/fonts/Nunito.ttf'),24)
 BOLD=ImageFont.truetype(str(ROOT/'apps/devcat_flutter/assets/fonts/Nunito.ttf'),29)
 blocks=[]
 for box in boxes:
  lines=[]
  for line in str(box).splitlines():lines+=textwrap.wrap(line,65,replace_whitespace=False) or ['']
  blocks.append(lines)
 height=100+sum(38+len(lines)*31+38 for lines in blocks)
 im=Image.new('RGB',(1040,height),'#f5f7ef');d=ImageDraw.Draw(im)
 d.text((35,20),title[:58],font=BOLD,fill='#203b30');y=80
 for i,lines in enumerate(blocks):
  h=30+len(lines)*31;d.rounded_rectangle((30,y,1010,y+h),radius=18,fill='#d9eee2' if i%2==0 else '#fffdf6',outline='#63967c',width=2)
  for j,line in enumerate(lines):d.text((50,y+15+j*31),line,font=FONT,fill='#203b30')
  y+=h+45
  if i<len(blocks)-1:d.text((505,y-37),'↓',font=BOLD,fill='#32654b')
 im.save(path,optimize=True)
 return name

def enrich(course):
 for lesson in course['lessons']:
  parts=lesson['id'].split('.');slug=parts[1] if len(parts)>1 else ''
  if slug in GLOSSARY and '.zero.' not in lesson['id']:
   lesson['sections'].insert(0,{'heading':'Сначала разберём новые слова','text':GLOSSARY[slug]+'\n\nЕсли пока трудно отличить код, ввод и результат, начни с раздела «С полного нуля» этого курса. Там каждое действие рассматривается отдельно. Не нужно понимать незнакомый термин до того, как увидел его работу.'})
  enriched=[]
  for section in lesson['sections']:
   section=dict(section);visual=section.get('visual')
   if visual:
    section['image']=png(visual['title'],[str(x) for x in visual['boxes']]);section['imageCaption']='Учебная схема конкретного опыта; не фотография интерфейса.'
   if section.get('code') and course['id'] not in ['html','css','git','sql']:
    code=section['code'];lines=code.splitlines()
    # Exact source is shown, with syntax reading aids kept distinct from runtime traces.
    section['image']=png('Читаем пример: '+lesson['title'],['Исходник: изучаем запись, а не готовый вывод',*['\n'.join(f'{j+1}: {lines[j]}' for j in range(i,min(i+6,len(lines)))) for i in range(0,len(lines),6)]])
    section['imageCaption']='Нумерация строк исходника. Порядок строк на схеме не является трассировкой циклов или ветвлений.'
    enriched.append(section)
    enriched.append({'heading':'Разметка записи: как прочитать этот пример','text':line_notes(course['id'],code)+'\n\nОбъяснение строки показывает её роль в записи. Чтобы проследить выполнение ветки или цикла, используй конкретный вход и таблицу состояния: при выполнении одна строка может повториться несколько раз или не выполниться вовсе.'})
   else:enriched.append(section)
  # A meaningful visual for non-code topics shows the actual stated assignment.
  if not any(s.get('image') for s in enriched):
   enriched.append({'heading':'Карта самостоятельного опыта','text':lesson['assignment'],'image':png(lesson['title'],[lesson['title'],lesson['assignment']]),'imageCaption':'Схема условия самостоятельного опыта.'})
  lesson['sections']=enriched;lesson['theory']='\n\n'.join(s.get('text','') for s in enriched);lesson['readingWords']=len(lesson['theory'].split())
 return course
